-- 同步 GPT-Image-2 的比例和分辨率基准；可重复执行，保留自定义白名单及历史任务。
UPDATE hub_ai_model
SET default_size = CASE default_size
    WHEN '1008x672' THEN '1536x1024'
    WHEN '672x1008' THEN '1024x1536'
    WHEN '2016x1344' THEN '2160x1440'
    WHEN '1344x2016' THEN '1440x2160'
    WHEN '2048x1152' THEN '2560x1440'
    WHEN '1152x2048' THEN '1440x2560'
    WHEN '1536x1152' THEN '1024x768'
    WHEN '1152x1536' THEN '768x1024'
    WHEN '1792x768' THEN '1344x576'
    ELSE default_size END,
    sizes = '1024x1024,2048x2048,2880x2880,1536x1024,2160x1440,3456x2304,1024x1536,1440x2160,2304x3456,1280x720,2560x1440,3840x2160,720x1280,1440x2560,2160x3840,1024x768,2048x1536,3200x2400,768x1024,1536x2048,2400x3200,1344x576,2016x864,3808x1632'
WHERE deleted = 0
  AND (model_code = 'gpt-image-2' OR model_code LIKE 'gpt-image-2-%')
  AND sizes IN (
    '1024x1024,1536x1024,1024x1536',
    '1024x1024,1536x1024,1024x1536,1280x720,720x1280,1536x1152,1152x1536,1792x768',
    '1024x1024,2048x2048,2880x2880,1008x672,2016x1344,3456x2304,672x1008,1344x2016,2304x3456,1280x720,2048x1152,3840x2160,720x1280,1152x2048,2160x3840,1024x768,2048x1536,3200x2400,768x1024,1536x2048,2400x3200,1344x576,2016x864,3808x1632'
  );
